BEGIN;
CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY);
CREATE TABLE accounts (id uuid PRIMARY KEY, name text NOT NULL, email text UNIQUE NOT NULL, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (token_hash text PRIMARY KEY, account_id uuid NOT NULL REFERENCES accounts(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE INDEX sessions_expiry_idx ON sessions(expires_at);
CREATE TABLE families (id uuid PRIMARY KEY, name text NOT NULL, created_by uuid NOT NULL REFERENCES accounts(id));
CREATE TABLE members (id uuid PRIMARY KEY, family_id uuid NOT NULL REFERENCES families(id) ON DELETE CASCADE, name text NOT NULL, created_by uuid NOT NULL REFERENCES accounts(id), account_id uuid REFERENCES accounts(id), status text NOT NULL DEFAULT 'unverified' CHECK(status IN ('unverified','verified')), profile jsonb NOT NULL DEFAULT '{}', UNIQUE(family_id,id), UNIQUE(family_id,account_id));
CREATE INDEX members_family_idx ON members(family_id);
CREATE TABLE memberships (family_id uuid REFERENCES families(id) ON DELETE CASCADE, account_id uuid REFERENCES accounts(id) ON DELETE CASCADE, member_id uuid NOT NULL, PRIMARY KEY(family_id,account_id), FOREIGN KEY(family_id,member_id) REFERENCES members(family_id,id) ON DELETE CASCADE);
CREATE TABLE relationships (id uuid PRIMARY KEY, family_id uuid NOT NULL REFERENCES families(id) ON DELETE CASCADE, from_id uuid NOT NULL, to_id uuid NOT NULL, type text NOT NULL CHECK(type IN ('parent','partner')), CHECK(from_id<>to_id), FOREIGN KEY(family_id,from_id) REFERENCES members(family_id,id) ON DELETE CASCADE, FOREIGN KEY(family_id,to_id) REFERENCES members(family_id,id) ON DELETE CASCADE, UNIQUE(family_id,from_id,to_id,type));
CREATE INDEX relationships_from_idx ON relationships(family_id,from_id);
CREATE INDEX relationships_to_idx ON relationships(family_id,to_id);
CREATE TABLE private_contacts (member_id uuid REFERENCES members(id) ON DELETE CASCADE, owner_id uuid REFERENCES accounts(id) ON DELETE CASCADE, ciphertext text NOT NULL, PRIMARY KEY(member_id,owner_id));
CREATE TABLE sharing (member_id uuid REFERENCES members(id) ON DELETE CASCADE, field text NOT NULL CHECK(field IN ('dob','city','email','religion','caste','gotra')), visibility text NOT NULL CHECK(visibility IN ('private','family','branch')), branch_root_id uuid REFERENCES members(id) ON DELETE CASCADE, PRIMARY KEY(member_id,field), CHECK(visibility<>'branch' OR branch_root_id IS NOT NULL));
CREATE TABLE messages (id uuid PRIMARY KEY, family_id uuid REFERENCES families(id) ON DELETE CASCADE, author_id uuid REFERENCES members(id) ON DELETE CASCADE, text text NOT NULL CHECK(length(text) BETWEEN 1 AND 2000), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX messages_family_time_idx ON messages(family_id,created_at DESC);
CREATE TABLE gatherings (id uuid PRIMARY KEY, family_id uuid REFERENCES families(id) ON DELETE CASCADE, title text NOT NULL, date timestamptz NOT NULL, location text NOT NULL, description text NOT NULL, created_by uuid REFERENCES accounts(id));
CREATE INDEX gatherings_family_time_idx ON gatherings(family_id,date);
CREATE TABLE audit_events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, actor_id uuid REFERENCES accounts(id) ON DELETE SET NULL, family_id uuid REFERENCES families(id) ON DELETE CASCADE, action text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO schema_migrations(version) VALUES ('001');
COMMIT;
